		String query = query(body, OUTPUTS + " ?seen", Modifier.DISTINCT);
		List<Statement> data = data();
		List<BindingSet> expected = expectedRows(Modifier.DISTINCT, false, true);
		assertThat(evaluate(parse(query), new RecordingStrategy(new RecordingTripleSource(data))))
				.containsExactlyInAnyOrderElementsOf(expected);

		RecordingStrategy strategy = new RecordingStrategy(new RecordingTripleSource(data));
		TupleExpr optimized = strategy.optimize(parse(query), new EvaluationStatistics(),
				EmptyBindingSet.getInstance());
		Union union = onlyUnion(optimized);
		List<BindingSet> actual = evaluate(optimized, strategy);

		assertAll(
				() -> assertThat(actual).containsExactlyInAnyOrderElementsOf(expected),
				() -> assertThat(strategy.inputs.get(union)).isNotEmpty()
						.allSatisfy(input -> assertThat(input.hasBinding("seed")).isFalse()));
